#!/usr/bin/env bash
# =============================================================================
# render-runtime-files.sh — Generate per-deployment runtime files from local.yaml
# =============================================================================
#
# Reads `config/local.yaml` (the single environment-specific source of truth,
# generated by scripts/bootstrap-assisted.sh or copied from
# config/local.yaml.example) and produces:
#
#   .cache/cilium-cluster<N>-values.yaml         (one per cluster, Helm input)
#   .cache/ping-exporter-cluster<N>-values.yaml  (one per cluster, Helm input)
#   .cache/test-env.sh                           (env vars for shell scripts)
#   .cache/test-env.json                         (same data, JSON for k6/JS)
#   deployments/alertmanager-config.yaml         (only if webhook_url is set)
#
# The .cache/ directory is gitignored. Re-run after editing local.yaml to
# regenerate. Cilium and ping_exporter Helm install commands point at
# .cache/ (see bootstrap-commands.sh produced by bootstrap-assisted.sh).
#
# Usage:
#   bash scripts/render-runtime-files.sh
#
# Dependencies: python3 + PyYAML (already in requirements.txt).
# =============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
cd "${REPO_ROOT}"

if [[ -t 1 ]]; then
    BOLD=$'\e[1m'; GREEN=$'\e[32m'; RED=$'\e[31m'; YELLOW=$'\e[33m'; RESET=$'\e[0m'
else
    BOLD=''; GREEN=''; RED=''; YELLOW=''; RESET=''
fi
ok()   { printf '%s✓%s %s\n' "${GREEN}" "${RESET}" "$*"; }
warn() { printf '%s!%s %s\n' "${YELLOW}" "${RESET}" "$*"; }
fail() { printf '%s✗%s %s\n' "${RED}"   "${RESET}" "$*"; exit 1; }

[[ -f "config/local.yaml" ]] || fail "config/local.yaml not found. Run scripts/bootstrap-assisted.sh first, or copy config/local.yaml.example."
mkdir -p .cache

# Single Python invocation — reads local.yaml, writes everything atomically.
python3 - <<'PYEOF'
import json
import sys
from pathlib import Path

import yaml

REPO_ROOT = Path.cwd()
LOCAL = REPO_ROOT / "config" / "local.yaml"
CACHE = REPO_ROOT / ".cache"
DEPLOY = REPO_ROOT / "deployments"

with open(LOCAL, encoding="utf-8") as f:
    cfg = yaml.safe_load(f)

clusters = cfg.get("clusters", [])
# `clusters` may be a list (canonical) or a dict — handle both.
if isinstance(clusters, dict):
    clusters = [{"name": k, **v} for k, v in clusters.items()]
if not isinstance(clusters, list) or len(clusters) < 2:
    sys.exit("ERROR: local.yaml must contain a `clusters:` list with N >= 2 entries")

ssh = cfg.get("ssh") or {}
ssh_user = ssh.get("user", "ubuntu")
ssh_key = ssh.get("key", "~/.ssh/id_ed25519")
alertmanager_url = (cfg.get("alertmanager") or {}).get("webhook_url") or ""

# ── Per-cluster Cilium Helm values ──────────────────────────────────────────
def render_cilium_values(self_idx: int, cluster: dict, peers: list) -> str:
    cluster_id = self_idx + 1
    name = cluster["name"]
    own_ip = cluster["ip"]

    peer_yaml = "\n".join(
        f"    - ips:\n      - {p['ip']}\n      name: {p['name']}\n      port: 32379"
        for p in peers
    )

    if cluster_id == 1:
        ipam_block = (
            "ipam:\n"
            "  operator:\n"
            "    clusterPoolIPv4PodCIDRList: 10.42.0.0/16"
        )
    else:
        ipam_block = (
            f"# IPAM mode: inherits from K3s --cluster-cidr=10.{41+cluster_id}.0.0/16.\n"
            "ipam:\n"
            "  mode: kubernetes"
        )

    return f"""# Auto-generated by scripts/render-runtime-files.sh from config/local.yaml
# DO NOT EDIT BY HAND — re-run the script after modifying local.yaml.

cluster:
  id: {cluster_id}
  name: {name}

clustermesh:
  apiserver:
    service:
      type: NodePort
    tls:
      auto:
        enabled: true
        method: cronJob
        schedule: "0 0 1 */4 *"
  config:
    clusters:
{peer_yaml}
    enabled: true
  mcsapi:
    enabled: false
  useAPIServer: true

{ipam_block}

k8sServiceHost: {own_ip}
k8sServicePort: 6443
kubeProxyReplacement: true

operator:
  replicas: 1

routingMode: tunnel
tunnelProtocol: vxlan

certgen:
  cronJob:
    successfulJobsHistoryLimit: 0

standaloneDnsProxy:
  enabled: false

hubble:
  enabled: true
  listenAddress: ":4244"
  metrics:
    enableOpenMetrics: true
    enabled:
      - "httpV2:exemplars=true;labelsContext=source_namespace,source_workload,destination_namespace,destination_workload,traffic_direction"
      - "drop"
      - "tcp"
      - "flow"
      - "icmp"
      - "dns"
    serviceMonitor:
      enabled: true
      labels:
        release: prometheus-stack
      interval: "15s"
"""


def render_ping_values(self_idx: int, cluster: dict, peers: list) -> str:
    targets_yaml = "\n".join(
        f'    - host: {p["ip"]}\n      name: "{p["name"]}"' for p in peers
    )
    return f"""# Auto-generated by scripts/render-runtime-files.sh from config/local.yaml
config:
  targets:
{targets_yaml}

  interval: 1s
  timeout: 3s
  payload-size: 56

serviceMonitor:
  enabled: true
  namespace: observability
  labels:
    release: prometheus-stack

service:
  type: ClusterIP
  port: 9427

resources:
  requests:
    memory: "32Mi"
    cpu: "10m"
  limits:
    memory: "64Mi"
    cpu: "50m"
"""


written = []
for i, cluster in enumerate(clusters):
    peers = [c for j, c in enumerate(clusters) if j != i]

    out = CACHE / f"cilium-{cluster['name']}-values.yaml"
    out.write_text(render_cilium_values(i, cluster, peers), encoding="utf-8")
    written.append(out)

    out = CACHE / f"ping-exporter-{cluster['name']}-values.yaml"
    out.write_text(render_ping_values(i, cluster, peers), encoding="utf-8")
    written.append(out)

# ── test-env.sh — sourceable env vars for shell scripts ─────────────────────
env_lines = [
    "#!/usr/bin/env bash",
    "# Auto-generated by scripts/render-runtime-files.sh from config/local.yaml.",
    "# `source` this file in any script that needs cluster IPs / names / kubeconfig.",
    "",
    f'export DMOS_SSH_USER="{ssh_user}"',
    f'export DMOS_SSH_KEY="{ssh_key}"',
    f'export DMOS_CLUSTER_COUNT={len(clusters)}',
    "",
    f'export DMOS_CLUSTER_NAMES=({" ".join(c["name"] for c in clusters)})',
    f'export DMOS_CLUSTER_IPS=({" ".join(c["ip"] for c in clusters)})',
    f'export DMOS_CLUSTER_REGIONS=({" ".join(c["region"] for c in clusters)})',
    "",
]
for i, c in enumerate(clusters, start=1):
    env_lines.append(f'export DMOS_CLUSTER{i}_NAME="{c["name"]}"')
    env_lines.append(f'export DMOS_CLUSTER{i}_IP="{c["ip"]}"')
    env_lines.append(f'export DMOS_CLUSTER{i}_REGION="{c["region"]}"')
    env_lines.append(f'export DMOS_CLUSTER{i}_KUBECONFIG="{c["kubeconfig_path"]}"')
    netem = c.get("netem") or {}
    env_lines.append(
        f'export DMOS_CLUSTER{i}_NETEM_DELAY_MS="{netem.get("delay_ms", 0)}"'
    )
    env_lines.append(
        f'export DMOS_CLUSTER{i}_NETEM_JITTER_MS="{netem.get("jitter_ms", 0)}"'
    )
    env_lines.append(
        f'export DMOS_CLUSTER{i}_NETEM_INTERFACE="{netem.get("interface", "")}"'
    )
    env_lines.append("")
env_path = CACHE / "test-env.sh"
env_path.write_text("\n".join(env_lines), encoding="utf-8")
written.append(env_path)

# ── test-env.json — for k6 / JS scripts that import JSON ─────────────────────
json_payload = {
    "ssh": {"user": ssh_user, "key": ssh_key},
    "clusters": [
        {
            "name": c["name"],
            "ip": c["ip"],
            "region": c["region"],
            "display_name": c.get("display_name", c["name"]),
            "ingress_url": f"http://{c['ip']}:30080",
            # Porta Prometheus: legge prometheus_port da local.yaml (per cluster);
            # default 32090 (kube-prometheus-stack via proxmox-k3s).
            "prometheus_url": f"http://{c['ip']}:{c.get('prometheus_port', 32090)}",
            "kubeconfig_path": c["kubeconfig_path"],
            "netem": c.get("netem") or {},
        }
        for c in clusters
    ],
}
json_path = CACHE / "test-env.json"
json_path.write_text(json.dumps(json_payload, indent=2) + "\n", encoding="utf-8")
written.append(json_path)

# ── deployments/alertmanager-config.yaml (only if webhook_url is set) ───────
if alertmanager_url and not alertmanager_url.startswith("<"):
    template = DEPLOY / "alertmanager-config.yaml.template"
    output = DEPLOY / "alertmanager-config.yaml"
    if template.exists():
        body = template.read_text(encoding="utf-8")
        body = body.replace("<OPERATOR_WEBHOOK_URL>", alertmanager_url)
        output.write_text(body, encoding="utf-8")
        written.append(output)

print(f"Rendered {len(written)} files from config/local.yaml:")
for p in written:
    print(f"  {p}")
PYEOF

ok "Render complete."
